"Handymen can take jobs under $1,000 total (labor and materials), no permits, nothing inside walls (California B&P Code §7048).": "El handyman puede hacer trabajos de menos de $1,000 en total (mano de obra y materiales), sin permisos y nada dentro de las paredes (Código B&P de California §7048).",
"Hide a review only if it breaks the rules (fake, threat, abuse, personal data, competitor). Honest negative reviews stay (FTC rule, California Civil Code §1670.8).": "Oculte una reseña solo si rompe las reglas (falsa, amenaza, insulto, datos personales, competidor). Las reseñas negativas honestas se quedan (regla de la FTC, Código Civil de California §1670.8).",
