"NovaFides jobs in your phone calendar": "Trabajos de NovaFides en el calendario de su teléfono",
"Subscribe once: new and changed jobs appear in your Google, Apple or Outlook calendar automatically (calendar apps check every 15 minutes to a few hours).": "Suscríbase una vez: los trabajos nuevos y los cambios aparecen solos en su calendario de Google, Apple u Outlook (las apps revisan cada 15 minutos o cada pocas horas).",
"Open in Apple Calendar": "Abrir en Calendario de Apple",
"Add to Google Calendar": "Agregar a Google Calendar",
"Keep this link private: anyone with it can see your job times and addresses.": "No comparta este enlace: quien lo tenga puede ver horarios y direcciones de sus trabajos.",
"Make a new link (the old one stops working)": "Crear un enlace nuevo (el anterior deja de funcionar)",
"Create my calendar link": "Crear mi enlace de calendario",
"Block busy time from your own calendar": "Bloquear horas ocupadas de su propio calendario",
"Paste the secret iCal address of your calendar. Times when you are busy there disappear from your free slots on NovaFides. We store only the times, not the titles.": "Pegue la dirección secreta iCal de su calendario. Las horas ocupadas allí desaparecen de sus horarios libres en NovaFides. Solo guardamos las horas, no los títulos.",
"Where to find the secret address": "Dónde encontrar la dirección secreta",
"Google Calendar (on a computer): Settings → your calendar → Integrate calendar → “Secret address in iCal format”.": "Google Calendar (en computadora): Configuración → su calendario → Integrar calendario → “Dirección secreta en formato iCal”.",
"Apple iCloud: Calendar app → calendar info → Public Calendar → copy link.": "Apple iCloud: app Calendario → información del calendario → Calendario público → copiar enlace.",
"Outlook: Settings → Calendar → Shared calendars → Publish a calendar → ICS link.": "Outlook: Configuración → Calendario → Calendarios compartidos → Publicar un calendario → enlace ICS.",
"Save and sync": "Guardar y sincronizar",
"Sync now": "Sincronizar ahora",
"Last sync": "Última sincronización",
"{n} busy blocks in the next 30 days": "{n} bloques ocupados en los próximos 30 días",
"Use the secret iCal address from Google, Apple iCloud or Outlook calendar.": "Use la dirección secreta iCal de Google, Apple iCloud u Outlook.",
"That sign-in link did not work. Open the link on the same phone or computer, in the same browser, where you asked for it. Or ask for a new email below.": "Ese enlace no funcionó. Ábralo en el mismo teléfono o computadora, en el mismo navegador donde lo pidió, o pida un correo nuevo abajo.",
"Too many sign-in emails were sent in the last hour. Please try again in an hour.": "Se enviaron demasiados correos de acceso en la última hora. Intente de nuevo en una hora.",
