"The sheet fits Avery 8371 / 5371 business card paper, or any print shop: print at 100% scale, both sides. The QR code works on any phone camera.": "La hoja sirve para papel de tarjetas Avery 8371 / 5371 o cualquier imprenta: imprima al 100%, por ambos lados. El código QR funciona con la cámara de cualquier teléfono.",
"Print": "Imprimir",
