"Clients show finished work in their home and tag you. Confirm only jobs you really did: confirmed projects appear on your page and in the feed.": "Los clientes muestran trabajos terminados en su casa y le etiquetan. Confirme solo trabajos que realmente hizo: los proyectos confirmados aparecen en su página y en el feed.",
