"Typical totals for the Bay Area (labor and standard parts). Your pro gives the exact price in a quote before the work starts.": "Totales típicos del Área de la Bahía (mano de obra y piezas estándar). El profesional da el precio exacto en un presupuesto antes de empezar.",
"Verified pros who do this job": "Profesionales verificados que hacen este trabajo",
"Verified pros who work in and near {city}: real photos, their own work and honest reviews. You choose one pro; your request goes only to them.": "Profesionales verificados que trabajan en {city} y cerca: fotos reales, sus propios trabajos y reseñas honestas. Usted elige un profesional y su solicitud va solo a esa persona.",
