"What changes the price": "Qué cambia el precio",
"Whether the panel has room and enough capacity": "Si el panel tiene espacio y capacidad suficiente",
"Without a contractor license, a person may only take jobs under $1,000 total, with no building permit and no hired workers.": "Sin licencia de contratista, una persona solo puede aceptar trabajos de menos de $1,000 en total, sin permiso de construcción y sin empleados.",
