"visit": "visita",
"Add a technician": "Agregar un técnico",
"Add technicians on the Business page: fill in a technician’s name and trade yourself, or just create an invite link.": "Agregue técnicos en la página Empresa: complete usted el nombre y el oficio, o solo cree un enlace de invitación.",
"Afternoon 12–5": "Tarde 12–5",
"Any time": "Cualquier hora",
"Are you a pro or a company?": "¿Es profesional o empresa?",
"Ask {name} to call me": "Pedir a {name} que me llame",
"Call": "Llamar",
"Calls": "Llamadas",
"Clients: no separate sign-up": "Clientes: sin registro aparte",
"Company sign-up · step 1 of 2": "Registro de empresa · paso 1 de 2",
"Contact {name}": "Contactar a {name}",
"Copy link": "Copiar enlace",
"Create the invite link": "Crear el enlace de invitación",
"E.g. Water heater leaks from the bottom, 40 gallons, about 10 years old.": "Ej.: El calentador gotea por abajo, 40 galones, unos 10 años.",
"Empty technician invite": "Invitación de técnico vacía",
"Enter a phone number with area code.": "Escriba un número con código de área.",
"Enter the 6-digit code from the email. Done: no password, no form.": "Escriba el código de 6 dígitos del correo. Listo: sin contraseña ni formulario.",
"Enter your email and the 6-digit code from the email. That is it: your account is created. No password.": "Escriba su correo y el código de 6 dígitos que le llega. Eso es todo: su cuenta queda creada. Sin contraseña.",
"Enter your email and the code we send. Next you add the company: name, license, colors. Then you invite your technicians.": "Escriba su correo y el código que enviamos. Luego agregue la empresa: nombre, licencia, colores. Después invite a sus técnicos.",
"Enter your email and the code we send. Next you check the profile your office prepared and join the team.": "Escriba su correo y el código que enviamos. Luego revise el perfil que preparó su oficina y únase al equipo.",
"Enter your email and the code we send. Next you fill in your profile: photo, trade, license, services, prices and hours.": "Escriba su correo y el código que enviamos. Luego complete su perfil: foto, oficio, licencia, servicios, precios y horario.",
"Estimate: describe the problem and add photos, the pro answers in the chat. Call back: leave your number and when it is convenient.": "Presupuesto: describa el problema y agregue fotos, el profesional responde en el chat. Que le llamen: deje su número y cuándo le conviene.",
"Evening 5–8": "Noche 5–8",
"Fill in the profile: real photo, trade, CSLB license, services and prices, days and hours.": "Complete el perfil: foto real, oficio, licencia CSLB, servicios y precios, días y horas.",
"How sign-up works": "Cómo funciona el registro",
"Mon–Fri 8am–6pm": "Lun–Vie 8am–6pm",
"Morning 8–12": "Mañana 8–12",
"NovaFides checks the license and ID, then the profile goes public.": "NovaFides verifica la licencia y la identidad; después el perfil se publica.",
"Optional. If you add a number, clients see a “Call” button on your page. Without it, clients write to you or ask for a call back.": "Opcional. Si agrega un número, los clientes ven el botón “Llamar” en su página. Sin él, le escriben o piden que les llame.",
"Phone": "Teléfono",
"Phone on my page": "Teléfono en mi página",
"Pick a pro and book, ask for an estimate or a call back.": "Elija un profesional y reserve, pida un presupuesto o que le llamen.",
"Pro not found.": "Profesional no encontrado.",
"Pro sign-up · step 1 of 2": "Registro de profesional · paso 1 de 2",
"Request a call back": "Pedir que me llamen",
"Send the link by text or email. The technician opens it, checks the prepared profile, adds a photo and joins your team.": "Envíe el enlace por mensaje o correo. El técnico lo abre, revisa el perfil preparado, agrega una foto y se une a su equipo.",
"Short description of the problem (optional)": "Breve descripción del problema (opcional)",
"Tap “Sign in”, enter your email.": "Toque “Entrar” y escriba su correo.",
"Team invite · step 1 of 2": "Invitación al equipo · paso 1 de 2",
"The chat opens with this message. You can add photos there.": "El chat se abre con este mensaje. Ahí puede agregar fotos.",
"The office filled in the basics: check them, add your real photo and your services.": "La oficina completó lo básico: revíselo, agregue su foto real y sus servicios.",
"Then send the link by SMS or email. The technician signs in with their own email, adds a real photo and their services, and joins your team. Reviews and job counts always belong to the technician.": "Luego envíe el enlace por SMS o correo. El técnico entra con su propio correo, agrega su foto real y sus servicios, y se une a su equipo. Las reseñas y los trabajos siempre son del técnico.",
"This is an example profile: the form shows how it works, but sending is turned off. With a real pro, your request goes to them.": "Este es un perfil de ejemplo: el formulario muestra cómo funciona, pero el envío está desactivado. Con un profesional real, su solicitud le llega.",
"What time?": "¿A qué hora?",
"When is it convenient?": "¿Cuándo le conviene?",
"When you take calls": "Cuándo atiende llamadas",
"Write a few words.": "Escriba unas palabras.",
"Write to {name}": "Escribir a {name}",
"Your message": "Su mensaje",
"Your number goes only to {name}, in your chat. It is not shown anywhere else.": "Su número llega solo a {name}, en su chat. No se muestra en ningún otro lugar.",
"Your phone": "Su teléfono",
"fill in the basics, the technician finishes the profile": "complete lo básico, el técnico termina el perfil",
"join {company} on NovaFides: open the link, sign in with your email and check your profile.": "únase a {company} en NovaFides: abra el enlace, entre con su correo y revise su perfil.",
"waiting to join": "esperando unirse",
"{name} got your call-back request with your number and convenient time. You can also write here.": "{name} recibió su pedido de llamada con su número y horario. También puede escribir aquí.",
"{name} will call you back": "{name} le devolverá la llamada",
"“Create pro profile” → email and code.": "“Crear perfil de profesional” → correo y código.",
"“Register company” → email and code → company name, license, colors.": "“Registrar empresa” → correo y código → nombre, licencia, colores.",
"Only they will call you.": "Solo te llamará quien elijas.",
"Three simple steps": "Tres pasos sencillos",
"A client’s request is never sold to five pros who then race to call first. The client picks you, and the request goes only to you.": "La solicitud de un cliente nunca se vende a cinco profesionales que compiten por llamar primero. El cliente le elige a usted y la solicitud le llega solo a usted.",
"Find a verified plumber, electrician, handyman or builder in the Bay Area. Real photos, real work, honest reviews. You choose one pro; your request goes only to them. Free for clients.": "Encuentre un plomero, electricista, handyman o constructor verificado en el Área de la Bahía. Fotos reales, trabajos reales, reseñas honestas. Usted elige un profesional y su solicitud le llega solo a esa persona. Gratis para clientes.",
