"Location is not available on this device.": "La ubicación no está disponible en este dispositivo.",
"Location was not allowed. Click the map or type a city.": "No se permitió la ubicación. Haga clic en el mapa o escriba una ciudad.",
"City or ZIP in California": "Ciudad o código postal en California",
"My location": "Mi ubicación",
"Click the map or drag the pin to the center of your area, then set how far you travel.": "Haga clic en el mapa o arrastre el punto al centro de su zona y luego elija hasta dónde se desplaza.",
"I travel up to": "Me desplazo hasta",
"mi": "mi",
