"{name} is not taking new jobs right now and may not answer soon. Do you still want to write?": "{name} no acepta trabajos nuevos en este momento y puede tardar en responder. ¿Quiere escribirle de todos modos?",
"{name} is not taking new jobs right now and may not answer soon. You can still write.": "{name} no acepta trabajos nuevos en este momento y puede tardar en responder. Aun así puede escribirle.",
"Reviews on other sites": "Reseñas en otros sitios",
"See what clients say about {name} elsewhere too.": "Vea también lo que dicen los clientes de {name} en otros sitios.",
"{name} is new on NovaFides. Open their profiles on other sites to read their history there.": "{name} es nuevo en NovaFides. Abra sus perfiles en otros sitios para leer su historial allí.",
"NovaFides checked that these profiles belong to this pro.": "NovaFides comprobó que estos perfiles pertenecen a este profesional.",
"Links added by the pro; NovaFides has not checked them yet.": "Enlaces agregados por el profesional; NovaFides aún no los ha comprobado.",
"Ratings there are not ours: open the site to see them.": "Las calificaciones de allí no son nuestras: abra el sitio para verlas.",
"Reviews on": "Reseñas en",
"Already have reviews on Yelp, Google or Thumbtack? Add the links: clients see buttons to your profiles there and can read your history. We show only links, never copy ratings.": "¿Ya tiene reseñas en Yelp, Google o Thumbtack? Agregue los enlaces: los clientes ven botones a sus perfiles y pueden leer su historial. Mostramos solo enlaces, nunca copiamos calificaciones.",
"After you save, a NovaFides admin checks that the profiles are yours.": "Después de guardar, un administrador de NovaFides comprueba que los perfiles son suyos.",
"Saved. NovaFides will check that these profiles are yours.": "Guardado. NovaFides comprobará que estos perfiles son suyos.",
