"Tools": "Herramientas",
"No friends yet.": "Aún no hay amigos.",
"All friends": "Todos los amigos",
"Find and add friends": "Buscar y añadir amigos",
"Your private list of pros from other trades: an electrician, a tile setter, a roofer you trust. Keep them here so you never lose them. Only you see this list, and the pro does not have to add you back.": "Tu lista privada de profesionales de otros oficios: un electricista, un azulejero, un techador de confianza. Guárdalos aquí para no perderlos. Solo tú ves esta lista y el profesional no tiene que añadirte.",
"In your list": "En tu lista",
"Add to my list": "Añadir a mi lista",
