"My note: e.g. good with panels, call after 5pm": "Mi nota: p. ej. bueno con paneles, llamar después de las 5",
"My note": "Mi nota",
"Your list is empty. Find a pro by name above and add them.": "Tu lista está vacía. Busca a un profesional por nombre arriba y añádelo.",
"Useful stores": "Tiendas útiles",
"Useful tools": "Herramientas útiles",
"Stores that pros of your trade recommend, with their advice. Only pros of your trade see this list and vote, so the rating is from people who do the same work.": "Tiendas que recomiendan los profesionales de tu oficio, con sus consejos. Solo los profesionales de tu oficio ven esta lista y votan, así que la calificación es de gente que hace el mismo trabajo.",
"Tools that pros of your trade recommend, with their advice. Only pros of your trade see this list and vote, so the rating is from people who do the same work.": "Herramientas que recomiendan los profesionales de tu oficio, con sus consejos. Solo los profesionales de tu oficio ven esta lista y votan, así que la calificación es de gente que hace el mismo trabajo.",
