"Write the name.": "Escribe el nombre.",
"Write in English (Latin letters), please.": "Escribe en inglés (letras latinas), por favor.",
"The link looks wrong. Copy it from the address bar.": "El enlace parece incorrecto. Cópialo de la barra de direcciones.",
"You have reached the limit of 40 tips.": "Has llegado al límite de 40 consejos.",
"Could not save. Try again.": "No se pudo guardar. Inténtalo de nuevo.",
"Choose a day": "Elige un día",
"Free day": "Día libre",
"Partly booked": "Parcialmente ocupado",
"Fully booked": "Todo ocupado",
"Choose a day to see the open times.": "Elige un día para ver las horas libres.",
"The pro looks at your job first": "Primero el profesional mira tu trabajo",
"Describe the job above and add photos. The pro answers with a price and about how long it takes. Only then you see the calendar and pick a time.": "Describe el trabajo arriba y añade fotos. El profesional responde con un precio y cuánto tarda aproximadamente. Solo entonces ves el calendario y eliges la hora.",
"The pro looks at your description and photos, then answers with a price and about how long the job takes. After that you pick a time.": "El profesional mira tu descripción y fotos y responde con un precio y cuánto tarda el trabajo. Después eliges la hora.",
"How to reach you": "Cómo contactarte",
"No password and no separate sign-up page: we email you a 6-digit code, you type it here and the request is sent. The answer of the pro comes to this email.": "Sin contraseña ni página de registro aparte: te enviamos un código de 6 dígitos por correo, lo escribes aquí y la solicitud se envía. La respuesta del profesional llega a este correo.",
"Phone (optional): the pro can call you back": "Teléfono (opcional): el profesional puede llamarte",
"Already have an account? Sign in": "¿Ya tienes cuenta? Inicia sesión",
"Not in the list: described by you": "No está en la lista: descrito por ti",
"The pro answers with a price": "El profesional responde con un precio",
"After the pro answers": "Después de que responda el profesional",
"Type it here and your request is sent.": "Escríbelo aquí y tu solicitud se envía.",
"Confirm and send": "Confirmar y enviar",
"My job is not in the list: I will describe it": "Mi trabajo no está en la lista: lo describiré",
"Start typing and pick your address from the list. It is shared only with the pro or office you book.": "Empieza a escribir y elige tu dirección de la lista. Solo la ve el profesional u oficina que reservas.",
"Describe the job in a few words: what needs to be done and where.": "Describe el trabajo en pocas palabras: qué hay que hacer y dónde.",
"a job that is not in the list": "un trabajo que no está en la lista",
"About how long the job takes": "Cuánto tarda el trabajo aproximadamente",
