"Every pro is tied to an ID check and, for plumbing and electrical, a CSLB license. One person, one profile. Deleting a profile does not erase its reviews.": "Каждый мастер привязан к проверке документа, а сантехники и электрики — к лицензии CSLB. Один человек — один профиль. Удаление профиля не стирает отзывы.",
"Experienced pro, shoe covers, tidy cleanup.": "Опытный мастер, бахилы, уборка после работы.",
"Fair for clients. Fair for pros.": "Честно для клиентов. Честно для мастеров.",
"Find a pro": "Найти мастера",
"First and last name": "Имя и фамилия",
"Five skills rated after every job. Negative reviews are never deleted.": "После каждой работы оцениваются пять навыков. Негативные отзывы никогда не удаляются.",
"Flat monthly subscription. No lead fees.": "Фиксированная подписка. Никакой платы за заявки.",
"For pros": "Мастерам",
