"For your safety, keep talking here until the booking is confirmed. Deals made outside NovaFides have no reviews, no record and no help if something goes wrong.": "Для вашей безопасности общайтесь здесь, пока запись не подтверждена. У договорённостей вне NovaFides нет отзывов, истории и помощи, если что-то пойдёт не так.",
