"Only clients with a finished booking can review. You rate five skills: punctuality, workmanship, cleanliness, communication and pricing transparency. Honest negative reviews are never removed. Pros may post one calm public reply of up to 600 characters. Reviews that are fake, abusive or not about the job can be reported to a moderator.": "Отзыв может оставить только клиент с выполненным заказом. Оцениваются пять навыков: пунктуальность, качество работы, чистота, общение и честность цены. Честные негативные отзывы никогда не удаляются. Мастер может один раз спокойно ответить публично, до 600 символов. На фальшивые, оскорбительные или не относящиеся к работе отзывы можно пожаловаться модератору.",
