"NovaFides jobs in your phone calendar": "Заказы NovaFides в календаре телефона",
"Subscribe once: new and changed jobs appear in your Google, Apple or Outlook calendar automatically (calendar apps check every 15 minutes to a few hours).": "Подпишитесь один раз: новые и изменённые заказы сами появятся в календаре Google, Apple или Outlook (приложения проверяют обновления от 15 минут до нескольких часов).",
"Open in Apple Calendar": "Открыть в Календаре Apple",
"Add to Google Calendar": "Добавить в Google Календарь",
"Keep this link private: anyone with it can see your job times and addresses.": "Не делитесь этой ссылкой: по ней видно время и адреса ваших заказов.",
"Make a new link (the old one stops working)": "Сделать новую ссылку (старая перестанет работать)",
"Create my calendar link": "Создать ссылку для календаря",
"Block busy time from your own calendar": "Занятое время из вашего календаря",
"Paste the secret iCal address of your calendar. Times when you are busy there disappear from your free slots on NovaFides. We store only the times, not the titles.": "Вставьте секретный iCal-адрес своего календаря. Время, когда вы там заняты, исчезнет из свободного времени на NovaFides. Мы храним только время, без названий событий.",
"Where to find the secret address": "Где найти секретный адрес",
"Google Calendar (on a computer): Settings → your calendar → Integrate calendar → “Secret address in iCal format”.": "Google Календарь (на компьютере): Настройки → ваш календарь → Интеграция календаря → «Закрытый адрес в формате iCal».",
"Apple iCloud: Calendar app → calendar info → Public Calendar → copy link.": "Apple iCloud: приложение Календарь → информация о календаре → Публичный календарь → скопировать ссылку.",
"Outlook: Settings → Calendar → Shared calendars → Publish a calendar → ICS link.": "Outlook: Параметры → Календарь → Общие календари → Опубликовать календарь → ссылка ICS.",
"Save and sync": "Сохранить и синхронизировать",
"Sync now": "Синхронизировать сейчас",
"Last sync": "Последняя синхронизация",
"{n} busy blocks in the next 30 days": "занятых промежутков на 30 дней: {n}",
"Use the secret iCal address from Google, Apple iCloud or Outlook calendar.": "Используйте секретный iCal-адрес из Google, Apple iCloud или Outlook.",
"That sign-in link did not work. Open the link on the same phone or computer, in the same browser, where you asked for it. Or ask for a new email below.": "Ссылка для входа не сработала. Откройте её на том же телефоне или компьютере и в том же браузере, где запрашивали вход, или запросите новое письмо ниже.",
"Too many sign-in emails were sent in the last hour. Please try again in an hour.": "За последний час отправлено слишком много писем для входа. Попробуйте снова через час.",
