"Choose your city or enter a ZIP code.": "Выберите город или укажите ZIP.",
"City or ZIP is enough for an estimate. The full address is needed only when you pick a visit time.": "Для оценки достаточно города или ZIP. Полный адрес нужен только при выборе времени визита.",
"Compare offers": "Сравнить предложения",
"Demo profile": "Демо-профиль",
"Describe the job in a few words or choose a service.": "Опишите работу в нескольких словах или выберите услугу.",
"Describe the job once and choose up to 3 pros by name. Only they get it. To write to one pro, use the button on their page.": "Опишите работу один раз и выберите до 3 мастеров по имени. Получат только они. Чтобы написать одному мастеру, нажмите кнопку на его странице.",
"Describe the problem with photos": "Описать проблему с фото",
"Each finished job is saved here: who did it, when, what was installed (brand and part number), photos, the quote and the invoice. Call the same pro again in one tap, or share them with a neighbor.": "Здесь сохраняется каждая выполненная работа: кто делал, когда, что установили (бренд и номер детали), фото, смета и счёт. Вызовите того же мастера одним нажатием или поделитесь им с соседом.",
"Each pro gets it in a separate chat and can answer or send a quote. City or ZIP is enough for now.": "Каждый мастер получит заявку в отдельном чате и сможет ответить или прислать смету. Пока достаточно города или ZIP.",
"Everything that was done in your home": "Всё, что делали в вашем доме",
"For now, send your photos straight to a pro: they will tell you what it is and what it costs.": "Пока отправьте фото напрямую мастеру: он скажет, что это и сколько стоит.",
"Goes only to": "Получит только",
