"Nothing here yet. Finished jobs appear here automatically.": "Пока пусто. Выполненные работы появятся здесь сами.",
"Order details": "Подробнее о заказе",
"Photos help the pro understand the job before coming. No faces or house numbers, please.": "Фото помогают мастеру понять работу ещё до приезда. Без лиц и номеров домов, пожалуйста.",
