"Send to {name}": "Отправить: {name}",
"Sent only to the pros you chose. Each answers in their own chat below.": "Отправлено только выбранным мастерам. Каждый ответит в своём чате ниже.",
"Sent to {name} only. They answer here or send a quote you can accept.": "Отправлено только мастеру {name}. Ответ придёт здесь — или смета, которую можно принять.",
"Services and your prices": "Услуги и ваши цены",
"Set by the company": "Определяет компания",
"Share this pro": "Поделиться мастером",
"Showing {trade} pros below.": "Ниже — мастера: {trade}.",
"The office picks a technician and you see who is coming in your orders. The final price is in the quote before work starts.": "Офис выберет техника, и вы увидите в заказах, кто приедет. Окончательная цена — в смете до начала работы.",
"This is a visit request. The pro confirms the time and you get a notification. The final price is in the quote before work starts.": "Это запрос на визит. Мастер подтвердит время — придёт уведомление. Окончательная цена — в смете до начала работы.",
"This is an example profile. It shows how NovaFides works; requests cannot be sent to it.": "Это пример профиля. Он показывает, как работает NovaFides; отправлять ему заявки нельзя.",
"This pro does not take messages right now.": "Этот мастер сейчас не принимает сообщения.",
"Trip fee": "Выезд",
"Try other words, pick a trade above, or describe the problem with a photo: pros will tell you what it is.": "Попробуйте другие слова, выберите профессию выше или опишите проблему с фото — мастера подскажут, что это.",
