"Only the first name, last initial and public activity are shown. Addresses and contacts are never public.": "Показываются только имя, первая буква фамилии и публичная активность. Адреса и контакты никогда не публикуются.",
"Pick 2 or 3 pros in the search with “Compare”.": "Отметьте 2–3 мастеров в поиске кнопкой «Сравнить».",
"Pick one more pro": "Отметьте ещё одного мастера",
