"Projects": "Проекты",
"Pros never pay for a place in this list. The order depends only on what you choose above.": "Мастера не платят за место в этом списке. Порядок зависит только от того, что вы выбрали выше.",
"Pros that clients with picks like yours are happy with, in any trade. Shown only when at least 3 clients agree; nobody sees who.": "Мастера любых специальностей, которыми довольны клиенты с похожим на ваш выбором. Показываются, только если совпадают минимум 3 клиента; кто именно — не видно никому.",
