"Share a project": "Поделиться проектом",
"Show finished work in your home and tag the pro who did it. It goes public after the pro confirms it was their job. Do not show faces, house numbers or anything private.": "Покажите готовую работу у себя дома и отметьте мастера, который её сделал. Проект станет публичным, когда мастер подтвердит, что это его работа. Не показывайте лица, номера домов и ничего личного.",
"Show finished work in your home and tag the pro.": "Покажите готовую работу у себя дома и отметьте мастера.",
"Show first": "Сначала показывать",
"Side by side": "Рядом",
