"Home pros in {city}": "Мастера для дома в {city}",
"In California, building work over $1,000 needs a CSLB license (usually B, general building).": "В Калифорнии строительные работы дороже $1,000 требуют лицензии CSLB (обычно B — общее строительство).",
"In California, electrical work over $1,000 (labor and materials) needs a CSLB C-10 license.": "В Калифорнии электромонтажные работы дороже $1,000 (работа и материалы) требуют лицензии CSLB C-10.",
"In California, plumbing work over $1,000 (labor and materials) needs a CSLB C-36 license.": "В Калифорнии сантехнические работы дороже $1,000 (работа и материалы) требуют лицензии CSLB C-36.",
"Labor and standard parts. Your pro gives the exact price in a quote before the work starts.": "Работа и стандартные детали. Точную цену мастер даёт в смете до начала работ.",
"Larger jobs ($1,000+ or with a permit) need a licensed contractor": "Крупные работы ($1,000+ или с разрешением) — только лицензированный подрядчик",
"Materials and hardware": "Материалы и крепёж",
