"Typical total in the Bay Area": "Обычная цена в Bay Area",
"Typical totals for the Bay Area (labor and standard parts). Your pro gives the exact price in a quote before the work starts.": "Обычные цены в Bay Area (работа и стандартные детали). Точную цену мастер даёт в смете до начала работ.",
"Verified pros who do this job": "Проверенные мастера для этой работы",
"Verified pros who work in and near {city}: real photos, their own work and honest reviews. You choose one pro; your request goes only to them.": "Проверенные мастера, которые работают в {city} и рядом: настоящие фото, собственные работы и честные отзывы. Вы выбираете одного мастера, и заявка уходит только ему.",
